+import test from "node:test";
+import assert from "node:assert/strict";
+import { stockValue } from "../src/domain/reports.js";
+import { fresh } from "./helpers.js";
+
+test("stock value total equals the sum of rounded lines", () => {
+  const store = fresh();
+  const report = stockValue(store);
+  const sumOfLines = report.lines.reduce((s, l) => s + l.valueCents, 0);
+  assert.equal(report.totalCents, sumOfLines);
+  assert.equal(report.totalCents, 9290);
+});
